async function loadQuickReplies(){try{const t=await fetch("/api/chat/quick-replies"),n=await t.json();n.success&&n.data&&displayQuickReplies(n.data)}catch(t){console.error("❌ Error loading quick replies:",t)}}function displayQuickReplies(t){const n=document.getElementById("quickReplies");n&&(n.innerHTML="",t.forEach(t=>{const a=document.createElement("button");a.className="quick-reply-btn",a.textContent=t.label,a.onclick=()=>{sendQuickReply(t.value),hideQuickReplies()},n.appendChild(a)}),showQuickReplies())}function showQuickReplies(){const t=document.getElementById("quickReplies");t&&(t.style.display="flex")}function hideQuickReplies(){const t=document.getElementById("quickReplies");t&&(t.style.display="none")}async function sendQuickReply(t){const n=document.getElementById("chatInput");n&&(n.value=t,await sendMessage())}async function sendSatisfactionSurvey(){try{const t=await fetch(`/api/chat/survey/${currentChatCode}`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({customer_name:currentChatSession?.customer_name||"Bạn"})});(await t.json()).success&&(console.log("✅ Survey sent"),await loadChatMessages())}catch(t){console.error("❌ Error sending survey:",t)}}async function submitSatisfactionRating(t,n=""){try{const a=await fetch("/api/chat/satisfaction",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({session_code:currentChatCode,rating:t,feedback:n})});(await a.json()).success&&(console.log("✅ Satisfaction rating submitted:",t),showNotification("✅","Cảm ơn đánh giá của bạn!","#10b981"),await loadChatMessages())}catch(t){console.error("❌ Error submitting rating:",t)}}async function loadSupportAgents(){try{const t=await fetch("/api/chat/agent-list"),n=await t.json();if(n.success&&n.data)return n.data}catch(t){return console.error("❌ Error loading agents:",t),[]}}async function assignAgentToChat(t,n){try{const a=await fetch(`/api/chat/assign-agent/${currentChatCode}`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({agent_id:t,agent_name:n})}),e=await a.json();if(e.success)return console.log("✅ Agent assigned:",n),await loadChatMessages(),e.data}catch(t){console.error("❌ Error assigning agent:",t)}}async function getChatStats(){try{const t=await fetch("/api/chat/stats"),n=await t.json();if(n.success)return n.data}catch(t){return console.error("❌ Error fetching chat stats:",t),null}}function formatChatTime(t){const n=new Date,a=new Date(t),e=n-a;return e<6e4?"Vừa xong":e<36e5?`${Math.floor(e/6e4)}p`:e<864e5?`${Math.floor(e/36e5)}h`:a.toLocaleDateString("vi-VN")}function createRatingButtons(){const t=document.createElement("div");return t.className="satisfaction-rating",t.innerHTML='\n        <div class="rating-prompt">Bạn thấy hài lòng không? (1-5 sao)</div>\n        <div class="rating-buttons">\n            <button class="rating-btn" data-rating="1" title="Rất không hài lòng">😞</button>\n            <button class="rating-btn" data-rating="2" title="Không hài lòng">😕</button>\n            <button class="rating-btn" data-rating="3" title="Bình thường">😐</button>\n            <button class="rating-btn" data-rating="4" title="Hài lòng">😊</button>\n            <button class="rating-btn" data-rating="5" title="Rất hài lòng">😍</button>\n        </div>\n    ',t.querySelectorAll(".rating-btn").forEach(n=>{n.onclick=async()=>{const a=n.getAttribute("data-rating");await submitSatisfactionRating(a),t.remove()}}),t}function initializeChatEnhancements(){window.__chatEnhancementsInitialized||(window.__chatEnhancementsInitialized=!0,loadQuickReplies(),setTimeout(()=>{"active"===currentChatSession?.status&&sendSatisfactionSurvey()},3e5))}window.addEventListener("chat:opened",()=>{setTimeout(initializeChatEnhancements,250)});